// Mood-based local discovery. Public OSM lookup is requested only after a user action.
const DISCOVERY_CATALOG='ryadom-discovery-places-v1';
const DISCOVERY_CITY_KEY='ryadom-places-city-v1';
const moodConfig={
  sad:{label:'Грустно',icon:'☁',hint:'Неспешная прогулка, книга или чашка чая. Выбирай только то, на что есть силы.',types:['park','garden','library','cafe','museum']},
  anxious:{label:'Тревожно',icon:'◌',hint:'Место, где можно сменить обстановку. Тишину и отсутствие людей лучше проверить самому.',types:['park','garden','library','cafe']},
  romantic:{label:'Романтично',icon:'♡',hint:'Прогулка, вид на город или уютное место для встречи.',types:['garden','viewpoint','cafe','restaurant','gallery']},
  joyful:{label:'Весело',icon:'✷',hint:'Места, где можно гулять, смотреть кино или быть среди людей.',types:['park','cinema','theatre','cafe','attraction']},
  calm:{label:'Спокойно',icon:'✿',hint:'Пространства для неторопливого времени.',types:['park','garden','library','museum']},
  inspired:{label:'Хочется нового',icon:'◇',hint:'Музей, галерея или книжное место могут дать новую мысль.',types:['museum','gallery','arts_centre','books','library']},
  tired:{label:'Устало',icon:'☕',hint:'Поблизости и без большого плана: кофе или короткая прогулка.',types:['cafe','park','garden']},
  social:{label:'Хочется общения',icon:'↗',hint:'Места для встречи. Загруженность и атмосферу уточни перед поездкой.',types:['cafe','restaurant','bar','cinema']}
};
const discovery={mood:'sad',center:null,label:'',results:[],loading:false,request:0,controller:null};
const discoveryCache=new Map();
const placesStatus=document.querySelector('#placesStatus');
function catalogPlaces(){try{const x=JSON.parse(localStorage.getItem(DISCOVERY_CATALOG)||'[]');return Array.isArray(x)?x:[]}catch{return []}}
function saveCatalog(place){let all=catalogPlaces().filter(x=>x.key!==place.key);all.unshift(place);localStorage.setItem(DISCOVERY_CATALOG,JSON.stringify(all.slice(0,150)))}
function distanceKm(a,b,c,d){if(![a,b,c,d].every(Number.isFinite))return null;const x=(c-a)*Math.PI/180,y=(d-b)*Math.PI/180,q=Math.sin(x/2)**2+Math.cos(a*Math.PI/180)*Math.cos(c*Math.PI/180)*Math.sin(y/2)**2;return 12742*Math.asin(Math.sqrt(q))}
function distanceText(place){if(!discovery.center||!Number.isFinite(place.lat))return 'Расстояние неизвестно';const km=distanceKm(discovery.center.lat,discovery.center.lon,place.lat,place.lon);return km<1?Math.round(km*1000/50)*50+' м':km.toFixed(1).replace('.',',')+' км'}
function kindLabel(type){return ({park:'Парк',garden:'Сад',library:'Библиотека',cafe:'Кафе',museum:'Музей',viewpoint:'Смотровая площадка',restaurant:'Ресторан',gallery:'Галерея',cinema:'Кинотеатр',theatre:'Театр',attraction:'Достопримечательность',arts_centre:'Арт-пространство',books:'Книжный магазин',bar:'Бар'})[type]||'Место'}
function categoryOf(tags){for(const key of ['leisure','amenity','tourism','shop'])if(tags?.[key])return tags[key];return 'other'}
function moodIcon(type){return ({cafe:'☕',restaurant:'◈',park:'✿',garden:'✿',library:'▤',museum:'◇',gallery:'◇',viewpoint:'↗',cinema:'▣',theatre:'✦',books:'▤',bar:'✧'})[type]||'⌖'}
function placeMatchesMood(place){return moodConfig[discovery.mood].types.includes(place.type)}
function setPlacesStatus(message){placesStatus.textContent=message}
function renderMoodButtons(){const root=document.querySelector('#placesMoods');root.replaceChildren();Object.entries(moodConfig).forEach(([key,m])=>{const button=document.createElement('button');button.className='places-mood'+(discovery.mood===key?' active':'');button.type='button';button.textContent=m.icon+' '+m.label;button.setAttribute('aria-pressed',discovery.mood===key?'true':'false');button.onclick=()=>{discovery.mood=key;renderMoodButtons();document.querySelector('#placesMoodHint').textContent=m.hint;if(discovery.center)searchNearby();else renderPlaces()};root.append(button)})}
function favoritePlaces(){const keys=placeFavorites(),all=[...catalogPlaces(),...placeVisits().map(row=>({key:placeKey(row.name,row.area||''),name:row.name,area:row.area||'',type:row.kind||'other',lat:row.lat,lon:row.lon}))];const seen=new Set();return all.filter(x=>{if(!keys.includes(x.key)||seen.has(x.key))return false;seen.add(x.key);return true}).sort((a,b)=>{const d1=discovery.center?distanceKm(discovery.center.lat,discovery.center.lon,a.lat,a.lon):null,d2=discovery.center?distanceKm(discovery.center.lat,discovery.center.lon,b.lat,b.lon):null;return (d1??999)-(d2??999)})}
function makePlaceCard(place,isFavorite){const card=document.createElement('article');card.className='discovery-card';const art=document.createElement('div');art.className='discovery-art type-'+place.type;art.textContent=moodIcon(place.type);card.append(art);const body=document.createElement('div');body.className='discovery-card-body';const top=document.createElement('div');top.className='discovery-card-top';const h=document.createElement('h3');h.textContent=place.name;const heart=document.createElement('button');heart.type='button';heart.className='discovery-heart'+(isFavorite?' active':'');heart.textContent=isFavorite?'♥':'♡';heart.setAttribute('aria-label',isFavorite?'Убрать из любимых: '+place.name:'В любимые: '+place.name);heart.onclick=()=>{let keys=placeFavorites();keys=keys.includes(place.key)?keys.filter(x=>x!==place.key):[...keys,place.key];localStorage.setItem(PLACE_FAVORITES_KEY,JSON.stringify(keys));if(!isFavorite)saveCatalog(place);renderPlaces()};top.append(h,heart);body.append(top);const meta=document.createElement('p');meta.className='discovery-meta';meta.textContent=[kindLabel(place.type),place.area,distanceText(place)].filter(Boolean).join(' · ');body.append(meta);
  const visits=placeVisits().filter(row=>placeKey(row.name,row.area||'')===place.key);if(visits.length){const memory=document.createElement('p');memory.className='discovery-memory';memory.textContent=visits.length===1?'Уже есть в твоём дневнике':`Отметок об этом месте в дневнике: ${visits.length}`;body.append(memory)}
  if(isFavorite&&!placeMatchesMood(place)){const aside=document.createElement('p');aside.className='discovery-aside';aside.textContent='Любимое место · под выбранное настроение может подойти другое';body.append(aside)}
  const actions=document.createElement('div');actions.className='discovery-actions';if(Number.isFinite(place.lat)&&Number.isFinite(place.lon)){const link=document.createElement('a');link.href=`https://www.openstreetmap.org/?mlat=${place.lat}&mlon=${place.lon}#map=17/${place.lat}/${place.lon}`;link.target='_blank';link.rel='noopener noreferrer';link.textContent='На карте ↗';actions.append(link)}const visited=document.createElement('button');visited.type='button';visited.textContent='Была/был здесь';visited.onclick=()=>markPlaceVisited(place);actions.append(visited);body.append(actions);card.append(body);return card}
function renderPlaces(){const root=document.querySelector('#placesResults');root.replaceChildren();const favorites=favoritePlaces();if(favorites.length){const block=document.createElement('section');block.className='places-block';const head=document.createElement('div');head.className='places-block-title';head.innerHTML='<span>01 / ТВОИ МЕСТА</span><h2>Любимые сначала</h2>';block.append(head);const grid=document.createElement('div');grid.className='discovery-grid';favorites.forEach(p=>grid.append(makePlaceCard(p,true)));block.append(grid);root.append(block)}
  const favoriteKeys=new Set(favorites.map(x=>x.key)),others=discovery.results.filter(x=>!favoriteKeys.has(x.key)).sort((a,b)=>{const fit=Number(placeMatchesMood(b))-Number(placeMatchesMood(a));if(fit)return fit;return distanceKm(discovery.center.lat,discovery.center.lon,a.lat,a.lon)-distanceKm(discovery.center.lat,discovery.center.lon,b.lat,b.lon)});
  if(others.length){const block=document.createElement('section');block.className='places-block';const head=document.createElement('div');head.className='places-block-title';head.innerHTML='<span>02 / ПОБЛИЗОСТИ</span><h2>Новые места рядом</h2>';block.append(head);const grid=document.createElement('div');grid.className='discovery-grid';others.slice(0,24).forEach(p=>grid.append(makePlaceCard(p,false)));block.append(grid);root.append(block)}
  if(!favorites.length&&!others.length){const empty=document.createElement('div');empty.className='places-empty-state';empty.innerHTML='<span>⌖</span><h2>Место найдётся</h2><p>Выбери настроение и нажми «Рядом со мной» или введи город. Любимые места из дневника появятся здесь первыми.</p>';root.append(empty)}
  const note=document.createElement('p');note.className='places-ranking-note';note.textContent='Порядок: сначала любимые, затем подходящие места по расстоянию. Рейтинги и популярность в соцсетях пока не доступны — мы не подменяем их количеством посещений.';root.append(note)}
function markPlaceVisited(place){const day=todayKey(),all=placeVisits();all.push({id:'p-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),day,name:place.name,area:place.area||'',kind:place.type==='cafe'?'cafe':['park','garden'].includes(place.type)?'park':['museum','gallery','theatre','cinema'].includes(place.type)?'culture':'other',time:'',feeling:'',note:'',lat:place.lat,lon:place.lon});savePlaceVisits(all);saveCatalog(place);selectedDay=day;calendarMonth=new Date();renderPlaces();setPlacesStatus('«'+place.name+'» добавлено в дневник за сегодня.');}
async function searchNearby(){if(!discovery.center)return;const request=++discovery.request;discovery.controller?.abort();const cacheKey=[discovery.center.lat.toFixed(3),discovery.center.lon.toFixed(3),discovery.mood].join('|');const cached=discoveryCache.get(cacheKey);if(cached&&Date.now()-cached.at<15*60*1000){discovery.results=cached.results;setPlacesStatus(`Показано ${cached.results.length} мест рядом с «${discovery.label}».`);renderPlaces();return}discovery.loading=true;setPlacesStatus('Ищем места рядом с «'+discovery.label+'»…');renderPlaces();try{const {lat,lon}=discovery.center;const tags={park:'leisure',garden:'leisure',cafe:'amenity',library:'amenity',museum:'tourism',viewpoint:'tourism',restaurant:'amenity',gallery:'tourism',cinema:'amenity',theatre:'amenity',attraction:'tourism',arts_centre:'amenity',books:'shop',bar:'amenity'};const params=new URLSearchParams({lat:String(lat),lon:String(lon),radius:'2',limit:'80'});moodConfig[discovery.mood].types.forEach(type=>params.append('osm_tag',tags[type]+':'+type));const controller=new AbortController();discovery.controller=controller;const timeout=setTimeout(()=>controller.abort(),14000);let response;try{response=await fetch('https://photon.komoot.io/reverse?'+params,{signal:controller.signal})}finally{clearTimeout(timeout)}if(!response.ok)throw Error('Places '+response.status);const data=await response.json();if(request!==discovery.request)return;const seen=new Set();discovery.results=(data.features||[]).map(item=>{const p=item.properties||{},coordinates=item.geometry?.coordinates||[],lon=Number(coordinates[0]),lat=Number(coordinates[1]),name=p.name||'',type=p.osm_value||'other',area=p.street||p.district||p.city||'',key=placeKey(name,area),osmId=(p.osm_type||'')+'/'+p.osm_id;return {key,name,type,lat,lon,area,osmId}}).filter(p=>{if(!p.name||!Number.isFinite(p.lat)||!placeMatchesMood(p)||seen.has(p.osmId)||distanceKm(lat,lon,p.lat,p.lon)>2)return false;seen.add(p.osmId);return true});discoveryCache.set(cacheKey,{at:Date.now(),results:discovery.results});setPlacesStatus(discovery.results.length?`Найдено ${discovery.results.length} мест в радиусе около 2 км. Данные OpenStreetMap могут быть неполными.`:'Поблизости пока не нашлось мест под это настроение. Попробуй другой район или настроение.');renderPlaces()}catch(e){if(request!==discovery.request)return;discovery.results=[];setPlacesStatus('Поиск новых мест сейчас недоступен. Любимые места из дневника остаются здесь. Попробуй позже или укажи другой район.');renderPlaces()}finally{if(request===discovery.request){discovery.loading=false;discovery.controller=null}}}
document.querySelector('#placesLocate').onclick=()=>{if(!navigator.geolocation){setPlacesStatus('Этот браузер не поддерживает определение местоположения. Введи город вручную.');return}setPlacesStatus('Запрашиваем местоположение…');navigator.geolocation.getCurrentPosition(pos=>{discovery.center={lat:pos.coords.latitude,lon:pos.coords.longitude};discovery.label='текущей точки';localStorage.removeItem(DISCOVERY_CITY_KEY);searchNearby()},()=>setPlacesStatus('Не удалось получить местоположение. Введи город или район вручную.'),{enableHighAccuracy:false,timeout:10000,maximumAge:300000})};
document.querySelector('#placesCityForm').onsubmit=async event=>{event.preventDefault();const query=document.querySelector('#placesCity').value.trim();if(!query)return;const request=++discovery.request;setPlacesStatus('Ищем «'+query+'»…');try{const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),12000);let response;try{response=await fetch('https://nominatim.openstreetmap.org/search?format=json&limit=1&q='+encodeURIComponent(query),{signal:controller.signal})}finally{clearTimeout(timeout)}if(!response.ok)throw Error('Geocoding '+response.status);const hits=await response.json();if(request!==discovery.request)return;if(!hits.length){setPlacesStatus('Не удалось найти этот город или район. Попробуй уточнить название.');return}discovery.center={lat:Number(hits[0].lat),lon:Number(hits[0].lon)};discovery.label=hits[0].display_name.split(',').slice(0,2).join(',');localStorage.setItem(DISCOVERY_CITY_KEY,JSON.stringify({query,label:discovery.label,center:discovery.center}));searchNearby()}catch{if(request===discovery.request)setPlacesStatus('Не удалось найти город сейчас. Попробуй ещё раз позже или используй геолокацию.')}};
renderMoodButtons();renderPlaces();
try{const saved=JSON.parse(localStorage.getItem(DISCOVERY_CITY_KEY)||'null');if(saved&&Number.isFinite(saved.center?.lat)&&Number.isFinite(saved.center?.lon)){discovery.center=saved.center;discovery.label=saved.label;document.querySelector('#placesCity').value=saved.query;setPlacesStatus('Сохранён город «'+saved.label+'». Выбирай настроение — подборка обновится.');let opened=false;document.querySelectorAll('[data-view=places]').forEach(button=>button.addEventListener('click',()=>{if(!opened){opened=true;searchNearby()}}))}}catch{}
